function ForecastPage({theme}){const colors=paletteColors(theme);const [data,D]=useState(null),[summary,S]=useState(null),[err,E]=useState(''),[busy,B]=useState(true);async function load(){B(true);try{const [f,s]=await Promise.all([api.get('/forecast/cash-flow'),api.get('/dashboard/summary')]);D(f.data);S(s.data);E('')}catch(e){E(errorText(e))}finally{B(false)}}useEffect(()=>{load()},[]);async function recalc(){await api.post('/forecast/recalculate');load()}return <><PageTitle eyebrow="LOOK AHEAD" title="Cash-flow forecast" sub="A transparent estimate of how your balance could move through month end." action={<button className="secondary-btn" onClick={recalc}><Activity size={16}/> Recalculate</button>}/>{busy?<Loading/>:err?<ErrorBox error={err} retry={load}/>:<><div className="forecast-hero-grid"><div className="card forecast-big"><span>PROJECTED BALANCE · MONTH END</span><strong className={data.forecast.predicted_end_balance<0?'negative':''}>{money(data.forecast.predicted_end_balance)}</strong><p>At your recent spending pace, without assuming your next income arrives.</p><div className="forecast-separator"/><div className="scenario-line"><div><span>If expected income arrives</span><b>{money(data.forecast.predicted_with_expected_income)}</b></div><div><span>Expected expenses remaining</span><b>{money(data.forecast.expected_expenses)}</b></div></div></div><div className="card confidence-card"><div className="eyebrow">FORECAST QUALITY</div><div className="confidence-large">{Math.round(data.forecast.confidence*100)}<small>%</small></div><div className="quality-bar"><i style={{width:`${data.forecast.confidence*100}%`}}/></div><b>{data.forecast.confidence>.7?'Steady signal':data.forecast.confidence>.45?'Building confidence':'Early estimate'}</b><p>{data.forecast.days_remaining<7?'Short outlook window remaining.':'More transaction history helps improve this estimate.'} Estimates use historical daily expenses and compare moving average with a linear trend.</p><span className="model-badge">{data.forecast.model_version}</span></div></div><div className="card chart-card"><div className="card-head"><div><h3>Projected balance path</h3><p>Actual balance today, estimated daily balance from here</p></div><div className="chart-legend"><span><i className="legend-blue"/> Projected</span></div></div><div className="chart chart-forecast"><ChartSlot kind="forecast" data={data.points} colors={colors}/></div></div><div className="forecast-footnote"><AlertTriangle size={15}/><span>Expected income ({money(Math.max(0,data.forecast.predicted_with_expected_income-data.forecast.predicted_end_balance))}) is shown separately and is not treated as guaranteed. Forecasts are estimates and become more useful with several weeks of consistent entries.</span></div></>}</>}

function InsightAnalysis({data,theme}){const colors=paletteColors(theme);return <div className="feature-grid"><div className="card chart-card"><div className="card-head"><div><h3>Weekly spending comparison</h3><p>Rolling seven-day totals from your transactions</p></div></div><div className="chart"><ChartSlot kind="weekly-spending" data={data.weekly_spending} colors={colors}/></div></div><div className="card recurring-card"><div className="card-head"><div><h3>Budget outlook &amp; savings</h3><p>Projected from this month’s actual spending pace</p></div></div>{data.budget_risks?.length?data.budget_risks.slice(0,3).map(r=><div className="budget-row" key={r.category}><div className="budget-row-head"><div><b>{r.category}</b><span>{money(r.spent)} of {money(r.limit)} · pace projects {money(r.projected)}</span></div><strong className={r.overrun>0?'negative':''}>{r.overrun>0?money(r.overrun)+' over':'Watch'}</strong></div></div>):<EmptyMini text="No category budgets are at risk based on your current pace."/>}{data.savings_opportunities?.length>0&&<div className="savings-list">{data.savings_opportunities.slice(0,2).map(s=><p key={s.category}><b>{s.category}:</b> {s.reason}</p>)}</div>}</div></div>}
function Insights({theme}){const [data,D]=useState(null),[alerts,A]=useState([]),[busy,B]=useState(true),[err,E]=useState('');async function load(){B(true);try{const [i,a]=await Promise.all([api.get('/ai/insights'),api.get('/ai/anomalies')]);D(i.data);A(a.data);E('')}catch(e){E(errorText(e))}finally{B(false)}}useEffect(()=>{load()},[]);return <><PageTitle eyebrow="PATTERNS, MADE PLAIN" title="AI insights" sub="Simple explanations from your spending history. Outliers are prompts to review, not fraud findings."/>{busy?<Loading/>:err?<ErrorBox error={err} retry={load}/>:data.empty?<EmptyState title="Your insights are taking shape" text="Add a few expenses and we’ll uncover the patterns that matter." action={<NavLink className="primary-btn" to="/transactions">Add transactions</NavLink>}/>:<><div className="insight-grid">{data.insights.map((i,n)=><div className="card insight-card" key={n}><div className={`insight-symbol tone-${n%4}`}><Sparkles size={17}/></div><h3>{i.title}</h3><p>{i.detail}</p></div>)}</div><InsightAnalysis data={data} theme={theme}/><div className="card recurring-card"><div className="card-head"><div><h3>Recurring patterns</h3><p>Descriptions appearing three or more times</p></div></div>{data.recurring_expenses?.length?data.recurring_expenses.map(x=><div className="recurring-row" key={x.description}><span><Calendar size={16}/>{x.description}</span><small>{x.count} entries</small><b>{money(x.total)}</b></div>):<EmptyMini text="Recurring items will appear after enough transactions share a description."/>}</div><div className="card anomalies-card"><div className="card-head"><div><h3>Spending outliers</h3><p>Isolation Forest flags unusually large expense amounts in your history.</p></div><span className="alert-count">{alerts.length}</span></div>{alerts.length?alerts.map(a=><div className="anomaly-row" key={a.transaction_id}><div className="alert-symbol"><AlertTriangle size={15}/></div><div className="anomaly-main"><b>{a.description} <span>· {a.category}</span></b><p>{a.reason}</p></div><div className="anomaly-amount">{money(a.amount)}<small>{new Date(a.date+'T00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short'})}</small></div></div>):<div className="all-clear"><div className="clear-icon"><Check size={20}/></div><b>No outliers to review</b><span>With more history, SpendCount can spot unusual patterns more reliably.</span></div>}</div></>}</>}

function Planner(){
 const [plan,P]=useState(null),[commitments,C]=useState([]),[buffer,U]=useState(''),[delay,D]=useState(0),[busy,B]=useState(true),[err,E]=useState(''),[toast,T]=useState('');
 async function load(delayDays=delay){B(true);try{const [p,c,s]=await Promise.all([api.get(`/ai/weekly-plan?delay_income_days=${delayDays}`),api.get('/planning/commitments'),api.get('/planning/settings')]);P(p.data);C(c.data);U(String(s.data.emergency_buffer_target||''));E('')}catch(e){E(errorText(e))}finally{B(false)}}
 useEffect(()=>{load(0)},[]);
 async function addCommitment(e){e.preventDefault();const form=e.currentTarget,d=Object.fromEntries(new FormData(form));d.amount=Number(d.amount);try{await api.post('/planning/commitments',d);form.reset();T('Commitment added');load()}catch(e){E(errorText(e))}}
 async function deleteCommitment(id){try{await api.delete(`/planning/commitments/${id}`);T('Commitment removed');load()}catch(e){E(errorText(e))}}
 async function saveBuffer(e){e.preventDefault();try{await api.put('/planning/settings',{emergency_buffer_target:Number(buffer||0)});T('Emergency buffer goal saved');load()}catch(e){E(errorText(e))}}
 async function chooseDelay(value){D(Number(value));await load(Number(value))}
 return <><PageTitle eyebrow="A LITTLE MORE RUNWAY" title="Weekly planner" sub="Plan for delayed income, upcoming bills, and a buffer for unexpected costs." action={<button className="secondary-btn" onClick={()=>load()}><Activity size={16}/> Refresh plan</button>}/>{toast&&<div className="toast"><Check size={16}/>{toast}<button onClick={()=>T('')}><X size={14}/></button></div>}{busy?<Loading/>:err?<ErrorBox error={err} retry={()=>load()}/>:<>
 <div className="planner-hero"><div className="planner-hero-copy"><div className="eyebrow">YOUR FLEXIBLE WEEKLY CAP</div><strong>{money(plan.weekly_budget)}</strong><span>about {money(plan.daily_limit)} a day</span><p>{plan.explanation}</p></div><div className="planner-side"><div className="planner-stat"><span>Next income</span><b>{plan.days_until_income==null?'No date set':`${plan.days_until_income} days`}</b></div><div className="planner-stat"><span>Protected bills · 7 days</span><b>{money(plan.protected_upcoming_expenses)}</b></div><div className="planner-stat"><span>Income scenario</span><b>{plan.income_delay_scenario}</b></div></div></div>
 <div className="planning-tools"><div className="card planning-card"><div className="card-head"><div><h3>What if your income is late?</h3><p>Stress test your weekly spending cap without counting unconfirmed money.</p></div></div><label>Delay the next expected income<select value={delay} onChange={e=>chooseDelay(e.target.value)}><option value="0">On its expected date</option><option value="3">3 days late</option><option value="7">7 days late</option><option value="14">14 days late</option></select></label><div className="scenario-result"><span>{plan.income_delay_scenario}</span><b>{money(plan.weekly_budget)} weekly · {money(plan.daily_limit)} daily</b></div></div>
 <div className="card planning-card"><div className="card-head"><div><h3>Emergency buffer goal</h3><p>Set a reserve target; the planner protects a small share toward it.</p></div></div><form className="inline-planning-form" onSubmit={saveBuffer}><label>Target amount<input type="number" min="0" step="100" value={buffer} onChange={e=>U(e.target.value)} placeholder="e.g. 10000"/></label><button className="primary-btn">Save goal</button></form>{plan.emergency_buffer_target>0&&<div className="buffer-progress"><div><span>{money(Math.max(0,plan.current_balance))} current balance</span><b>{money(plan.emergency_buffer_gap)} to goal</b></div><div className="progress"><i style={{width:`${Math.min(100,Math.max(0,plan.current_balance)/plan.emergency_buffer_target*100)}%`}}/></div></div>}</div></div>
 <div className="card planning-card commitments-card"><div className="card-head"><div><h3>Upcoming commitments</h3><p>Track bills and planned costs for the next 30 days. Repeating entries are estimates.</p></div></div><form className="commitment-form" onSubmit={addCommitment}><label>Bill or cost<input name="title" required minLength="2" maxLength="120" placeholder="e.g. Hostel fee"/></label><label>Amount<input name="amount" type="number" min="1" required placeholder="5000"/></label><label>Category<select name="category">{EXPENSE.map(c=><option key={c}>{c}</option>)}</select></label><label>Due date<input name="due_date" type="date" min={localDate()} required/></label><label>Repeats<select name="recurring_frequency"><option value="one-time">One-time</option><option value="weekly">Weekly</option><option value="monthly">Monthly</option></select></label><button className="primary-btn"><Plus size={15}/> Add commitment</button></form>{plan.commitments_next_week?.length||commitments.length?<div className="commitment-list">{plan.commitments_next_week.map((x,i)=><div className="schedule-row" key={`${x.id}-${x.due_date}-${i}`}><div className="schedule-icon"><Calendar size={16}/></div><div><b>{x.title}</b><span>{x.category} · due {new Date(x.due_date+'T00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short'})}</span></div><strong>{money(x.amount)}</strong><button onClick={()=>deleteCommitment(x.id)} aria-label={`Remove ${x.title}`}><Trash2 size={14}/></button></div>)}</div>:<EmptyMini text="No bills entered yet. Add rent, subscriptions, or other upcoming costs."/>}</div>
 <div className="card suggestion-card"><div className="card-head"><div><h3>Category suggestions</h3><p>Limits based on your budgets and recent spending</p></div><span className="sparkle-chip"><Sparkles size={14}/> Personalised</span></div>{plan.suggestions.map((x,i)=><div className="suggestion-row" key={x.category}><div className="suggestion-number">{String(i+1).padStart(2,'0')}</div><div className="suggestion-copy"><b>{x.category}</b><p>{x.reason}</p></div><div className="suggestion-limit"><span>weekly target</span><b>{money(x.weekly_target)}</b></div></div>)}</div><div className="planner-note"><Sparkles size={16}/><span>{plan.disclaimer} Income remains excluded until you confirm it has arrived. Entered commitments and buffer targets are estimates you control.</span></div>
 </>}</>
}

function Settings({user, onUserUpdated, theme, onThemeChange}){const [schedules,S]=useState([]),[corrections,COR]=useState([]),[evalData,EVAL]=useState(null),[busy,B]=useState(true),[err,E]=useState(''),[toast,T]=useState(''),[name,setName]=useState(user?.name||''),[nameBusy,NB]=useState(false),[passOld,PO]=useState(''),[passNew,PN]=useState(''),[passBusy,PB]=useState(false),[avatarBusy,AB]=useState(false);
 async function load(){try{const [sc,co,ev]=await Promise.all([api.get('/income-schedules'),api.get('/ai/corrections'),api.get('/ai/model-evaluation').catch(()=>({data:null}))]);S(sc.data);COR(co.data);EVAL(ev.data)}catch(e){E(errorText(e))}finally{B(false)}}
 useEffect(()=>{load()},[]);
 async function add(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));d.expected_amount=Number(d.expected_amount);try{await api.post('/income-schedules',d);e.currentTarget.reset();T('Expected income added');load()}catch(e){E(errorText(e))}}
 async function del(x){await api.delete(`/income-schedules/${x.id}`);load()}
 async function updateProfileName(e){e.preventDefault();NB(true);try{const r=await api.put('/auth/profile',{name});onUserUpdated?.(r.data);T('Profile name updated')}catch(e){E(errorText(e))}finally{NB(false)}}
 async function updateAvatar(e){const file=e.target.files?.[0];e.target.value='';if(!file)return;if(!file.type.startsWith('image/')){E('Choose a JPG, PNG, or WebP image.');return}if(file.size>8*1024*1024){E('Choose an image smaller than 8 MB.');return}AB(true);E('');const reader=new FileReader();reader.onerror=()=>{E('Could not read the selected image.');AB(false)};reader.onload=()=>{const image=new Image();image.onerror=()=>{E('This image could not be opened.');AB(false)};image.onload=async()=>{const canvas=document.createElement('canvas'),scale=Math.min(1,512/Math.max(image.width,image.height));canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);const avatar_data_url=canvas.toDataURL('image/jpeg',.82);try{const r=await api.put('/auth/profile',{name,avatar_data_url});onUserUpdated?.(r.data);T('Profile photo updated')}catch(error){E(errorText(error))}finally{AB(false)}};image.src=reader.result};reader.readAsDataURL(file)}
 async function removeAvatar(){AB(true);E('');try{const r=await api.delete('/auth/profile/avatar');onUserUpdated?.(r.data);T('Profile photo removed')}catch(error){E(errorText(error))}finally{AB(false)}}
 function chooseTheme(value){onThemeChange(value);T('Theme updated and saved on this device')}
 async function updatePass(e){e.preventDefault();PB(true);try{await api.put('/auth/password',{old_password:passOld,new_password:passNew});PO('');PN('');T('Password updated successfully')}catch(e){E(errorText(e))}finally{PB(false)}}
 async function deleteCorrection(id){try{await api.delete(`/ai/corrections/${id}`);T('Correction removed');load()}catch(e){E(errorText(e))}}

 return <><PageTitle eyebrow="YOUR ACCOUNT" title="Profile settings" sub="Manage your profile, appearance, security, and planning preferences."/>
 {toast&&<div className="toast"><Check size={16}/>{toast}<button onClick={()=>T('')}><X size={14}/></button></div>}
 {err&&<ErrorBox error={err}/>}
 <div className="settings-grid">
   <div className="card account-card">
     <div className="card-head"><div><h3>Account profile</h3><p>Signed in to your personal finance workspace</p></div></div>
     <div className="account-identity"><div className="avatar large"><Avatar user={user}/></div><div><b>{user.name}</b><span>{user.email}</span></div></div>
     <div className="avatar-actions"><label className="avatar-upload secondary-btn"><ImagePlus size={15}/>{avatarBusy?'Saving photo…':'Upload profile photo'}<input type="file" accept="image/png,image/jpeg,image/webp" disabled={avatarBusy} onChange={updateAvatar}/></label>{user.avatar_data_url&&<button className="secondary-btn" type="button" disabled={avatarBusy} onClick={removeAvatar}>{avatarBusy?<LoaderCircle className="spin" size={15}/>:<Trash2 size={15}/>}Remove photo</button>}</div>
     <form className="settings-form" onSubmit={updateProfileName}>
       <label>Display Name<input value={name} onChange={e=>setName(e.target.value)} required minLength="2" maxLength="100"/></label>
       <button className="secondary-btn" disabled={nameBusy}>{nameBusy?<LoaderCircle className="spin" size={15}/>:<Check size={14}/>} Update Name</button>
     </form>
     <div className="forecast-separator" style={{margin:'20px 0 16px',background:'#eff1f5'}}/>
     <div className="card-head"><div><h3>Appearance</h3><p>Pick a color theme for your workspace.</p></div><Palette size={17}/></div>
     <label className="theme-select-label">Theme palette<select value={theme} onChange={e=>chooseTheme(e.target.value)}><option value="dark-gold">Midnight · warm gold (current dark)</option><option value="dark-forest">Forest · mint</option><option value="dark-ocean">Ocean · sky</option><option value="light-gold">Paper · warm gold</option><option value="light-sage">Sage · soft green</option></select></label>
     <div className="forecast-separator" style={{margin:'20px 0 16px',background:'#eff1f5'}}/>
     <div className="card-head"><div><h3>Security</h3><p>Update your password</p></div></div>
     <form className="settings-form" onSubmit={updatePass}>
       <label>Current Password<input type="password" required value={passOld} onChange={e=>PO(e.target.value)} placeholder="••••••••"/></label>
       <label>New Password<input type="password" required minLength="8" value={passNew} onChange={e=>PN(e.target.value)} placeholder="At least 8 characters"/></label>
       <button className="secondary-btn" disabled={passBusy}>{passBusy?<LoaderCircle className="spin" size={15}/>:<KeyRound size={14}/>} Change Password</button>
     </form>
     <div className="privacy-note"><div className="section-icon"><Check size={17}/></div><div><b>Private by design</b><p>Your financial records are strictly scoped to this account. SpendCount never asks for bank credentials or OTPs.</p></div></div>
   </div>
   <div className="card schedule-card">
     <div className="card-head"><div><h3>Expected income</h3><p>Planning estimates only. Incoming funds are never assumed guaranteed.</p></div></div>
     <form className="schedule-form" onSubmit={add}>
       <label>Source<input name="income_source" required placeholder="e.g. Family allowance"/></label>
       <label>Amount<input name="expected_amount" type="number" min="1" required placeholder="8500"/></label>
       <label>Expected date<input name="expected_date" type="date" required min={localDate()}/></label>
       <label>Frequency<select name="recurring_frequency"><option>one-time</option><option>weekly</option><option>monthly</option><option>semester</option></select></label>
       <button className="primary-btn"><Plus size={15}/> Add income estimate</button>
     </form>
     {busy?<Loading/>:schedules.length?schedules.map(x=><div className="schedule-row" key={x.id}><div className="schedule-icon"><ArrowDownRight size={17}/></div><div><b>{x.income_source}</b><span>{new Date(x.expected_date+'T00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})} · {x.recurring_frequency}</span></div><strong>{money(x.expected_amount)}</strong><button onClick={()=>del(x)}><Trash2 size={14}/></button></div>):<EmptyMini text="Add an expected income date to make your runway forecast more useful."/>}
     <div className="forecast-separator" style={{margin:'24px 0 16px',background:'#eff1f5'}}/>
     <div className="card-head"><div><h3>AI Feedback &amp; Corrections</h3><p>When you correct an AI category guess, it teaches your account's classifier</p></div><span className="count-pill">{corrections.length} recorded</span></div>
     {corrections.length?<div className="table-scroll"><table><thead><tr><th>TRANSACTION</th><th>AI GUESS</th><th>CORRECTED</th><th>DATE</th><th></th></tr></thead><tbody>{corrections.slice(0,6).map(c=><tr key={c.id}><td><b>{c.description}</b></td><td><span className="tag">{c.predicted_category}</span></td><td><span className="correction-badge">{c.corrected_category}</span></td><td className="muted-cell">{new Date(c.created_at).toLocaleDateString('en-IN',{day:'numeric',month:'short'})}</td><td className="row-actions"><button title="Remove" onClick={()=>deleteCorrection(c.id)}><Trash2 size={13}/></button></td></tr>)}</tbody></table></div>:<EmptyMini text="No manual corrections recorded yet. When you change an AI-suggested category, it appears here."/>}
     {evalData&&<div style={{marginTop:'22px'}}><div className="card-head"><div><h3>Model Transparency &amp; Evaluation</h3><p>Chronological 80/20 holdout comparison ({evalData.data_source==='synthetic_benchmark'?'Synthetic benchmark':'Personal history'})</p></div><BrainCircuit size={17} color="#d3a138"/></div><div className="eval-grid"><div className="eval-card"><b>Random Forest Regressor</b><span>MAE: ₹{evalData.random_forest?.mae||'N/A'}</span><span>RMSE: ₹{evalData.random_forest?.rmse||'N/A'}</span></div><div className="eval-card"><b>Moving Average Baseline</b><span>MAE: ₹{evalData.moving_average?.mae||'N/A'}</span><span>RMSE: ₹{evalData.moving_average?.rmse||'N/A'}</span></div></div><small style={{display:'block',marginTop:'8px',fontSize:'8.5px',color:'#9ca3af'}}>{evalData.note||'Estimates use historical daily spending. Forecasts are guidance, not guaranteed outcomes.'}</small></div>}
   </div>
 </div>
</>}

function EmptyMini({text}){return <div className="empty-mini"><div className="empty-mini-icon"><Activity size={17}/></div><span>{text}</span></div>}
function EmptyState({title,text,action}){return <div className="empty-state"><div className="empty-illustration"><WalletCards size={26}/></div><h3>{title}</h3><p>{text}</p>{action}</div>}
export default App
